pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount < 2 ether);
        address caller = address(0x1234);
        vm.deal(caller, 100 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}("");
        assertTrue(!success, "call with <2 ether should revert");
    }
}
